insert into public.kids_missions(season_id,code,mission_no,name,title,description,big_question,learning_goal,learning_objectives,stamp_name,next_mission_code,production_status,sort_order,is_active)
select s.id,x.code,x.mission_no,x.title,x.title,x.learning_goal,x.big_question,x.learning_goal,ARRAY[x.learning_goal]::text[],x.stamp_name,x.next_mission_code,x.production_status,x.sort_order,true
from src x join public.kids_seasons s on s.code=x.season_code
on conflict (code) do update set season_id=excluded.season_id, mission_no=excluded.mission_no, name=excluded.name, title=excluded.title, description=excluded.description,big_question=excluded.big_question,learning_goal=excluded.learning_goal, learning_objectives=excluded.learning_objectives,stamp_name=excluded.stamp_name,next_mission_code=excluded.next_mission_code, production_status=excluded.production_status,sort_order=excluded.sort_order,is_active=true,updated_at=now();
